sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float4 screen;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float2 center;
uniform float frequency;
uniform float strength;
uniform float phase;
uniform float radius;
uniform float feather;

half4 main(float2 coord) {
    float2 centerOffset = center / 1000.0 * float2(-1.0, 1.0);
    float2 sn = (coord - screen.xy) / max(screen.zw, float2(1.0));
    float3 lc3 = fromLayer * float3(layer * 0.5, 1.0);
    float2 lc = (lc3.xy / lc3.z - screen.xy) / max(screen.zw, float2(1.0));
    float2 st = sn - (lc - centerOffset);
    float aspect = screen.w / max(screen.z, 0.0001);
    st.y *= aspect;
    float featherSize = radius * 0.5 * feather;
    float innerRadius = max(0.0, radius - featherSize);
    float outerRadius = max(innerRadius + 0.00001, radius + featherSize);
    float dist = length(st);
    float damping = smoothstep(outerRadius, innerRadius, dist);
    float2 dir = dist > 0.000001 ? st / dist : float2(0.0);
    float2 offset = sin(dist * frequency * 6.2831853 + phase * 6.2831853) * strength * 0.5 * dir * damping;
    st += offset;
    st.y /= aspect;
    st += lc - centerOffset;
    return image.eval(screen.xy + st * screen.zw);
}
